// Signs a write-back for LendLoop's Convex endpoints: HMAC-SHA256 over
// `${timestamp}.${body}` with N8N_TO_CONVEX_SECRET (container env, never in this JSON).
const crypto = require('crypto');
function signForConvex(payload) {
  const secret = $env.N8N_TO_CONVEX_SECRET;
  if (!secret) throw new Error('N8N_TO_CONVEX_SECRET is not set in the n8n container');
  const body = JSON.stringify(payload);
  const timestamp = String(Math.floor(Date.now() / 1000));
  const digest = crypto.createHmac('sha256', secret).update(`${timestamp}.${body}`).digest('hex');
  return { body, timestamp, signature: `v1=${digest}` };
}

// Runs whenever a LendLoop workflow fails after its node-level retries.
// 1. Logs to the container output (docker compose logs n8n).
// 2. Reports to Convex so the failure shows in LendLoop's admin view.
// The execution id is the idempotency key: a retried report is not doubled.
const { execution = {}, workflow = {}, trigger } = $input.first().json;
const executionId = String(execution.id ?? trigger?.error?.timestamp ?? Date.now());
const node = execution.lastNodeExecuted ?? 'unknown node';
const message = (execution.error?.message ?? trigger?.error?.message ?? 'Unknown error').slice(0, 200);
const summary = `${workflow.name ?? 'Workflow'} failed at "${node}": ${message}`;
console.log(`[lendloop] WORKFLOW FAILED execution=${executionId} ${summary} ${execution.url ?? ''}`);
return [{ json: signForConvex({
  action: 'activity.record',
  idempotencyKey: `workflow_failed:${workflow.id ?? 'unknown'}:${executionId}`,
  kind: 'workflow_failed',
  summary,
  workflow: workflow.name ?? 'unknown',
  executionId,
}) }];
